UPDATE biz_lesson_class_scope
SET current_assigned = 0
WHERE lesson_id = #{lessonId}
  AND dept_id = #{deptId}
  AND entry_year = #{entryYear}
  AND class_code = #{classCode}

UPDATE biz_lesson_class_scope
SET current_assigned = 0
WHERE dept_id = #{deptId}
  AND entry_year = #{entryYear}
  AND class_code = #{classCode}
  AND lesson_id <> #{currentLessonId}
  AND current_assigned = 1
